type PlaceLegacyEventsParams struct {
	Scope   string
	TeamIds []uuid.UUID
	OrgID   uuid.UUID
	Seqs    []int64
}

// scope: system
// Sets the scope of legacy rows. A row placed meanwhile (scope no longer
// 'legacy') is not touched, so a second run, or a second instance, changes
// nothing. The events_scope_teams_check CHECK still holds the team rule.
func (q *Queries) PlaceLegacyEvents(ctx context.Context, arg PlaceLegacyEventsParams) (int64, error) {
	result, err := q.db.Exec(ctx, placeLegacyEvents,
		arg.Scope,
		arg.TeamIds,
		arg.OrgID,
		arg.Seqs,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
